using Microsoft.AspNetCore.DataProtection;using Microsoft.EntityFrameworkCore;using System.Security.Cryptography;using System.Text.RegularExpressions;
namespace Decont;
public record BundleRequest(long Version,string Name,long Size,string Mime,string Hash,string? Reason=null);
public record UploadGrant(Guid Report,Guid Document,string Actor,long Version,string Name,long Size,string Mime,string Hash,DateTime Expires);
public record BundleComplete(long Version,string Token,string? Reason=null);
public static class DocumentIntake {
 static IDataProtector Protector(HttpContext c)=>c.RequestServices.GetRequiredService<IDataProtectionProvider>().CreateProtector("decont.document-upload.v1");
 public static UploadGrant Read(HttpContext c,Guid report,string token){UploadGrant grant;try{grant=Serialization.Read<UploadGrant>(Protector(c).Unprotect(token));}catch(Exception e)when(e is CryptographicException or System.Text.Json.JsonException or FormatException or ArgumentException){throw new DomainException("upload_token","Autorizația de încărcare nu este validă. Selectează din nou fișierul.","Upload authorisation is invalid. Select the file again.",403);}Guard.Require(grant.Expires>DateTime.UtcNow&&grant.Report==report&&grant.Actor==Reports.Actor(c.User),"upload_token","Autorizația de încărcare a expirat sau aparține altui utilizator ori decont. Selectează din nou fișierul.","Upload authorisation expired or belongs to another user or report. Select the file again.",403);return grant;}
 public static async Task<(long File,long Report)> Limits(Db db){var policies=await db.Masters.Where(m=>m.Kind=="policies"&&m.Code=="uploads").ToListAsync();var p=policies.FirstOrDefault(m=>Rules.Effective(m,DateOnly.FromDateTime(DateTime.UtcNow)));return(p!=null&&Rules.Number(p,"maxFileMb")>0?(long)Rules.Number(p,"maxFileMb")*1024*1024:Files.MaxFile,p!=null&&Rules.Number(p,"maxReportMb")>0?(long)Rules.Number(p,"maxReportMb")*1024*1024:Files.MaxReport);}
 public static void Map(RouteGroupBuilder api){
  api.MapPost("/reports/{id:guid}/document-bundles",async(Guid id,BundleRequest input,HttpContext c,Db db,Reports svc)=>await Api.Atomic(db,c,input,async()=>{
   var report=await svc.Version(id,input.Version,c.User);svc.Edit(report,c.User,input.Reason);var limits=await Limits(db);Guard.Require(input.Size>0&&input.Size<=limits.File,"file_size","Fișierul depășește limita de încărcare.","File exceeds the upload limit.");Guard.Require(report.Attachments.Sum(a=>a.Size)+report.Lines.SelectMany(l=>l.Evidence).Sum(e=>e.Size)+input.Size<=limits.Report,"report_size","Documentele depășesc limita decontului.","Documents exceed the report limit.");
   Guard.Require(!string.IsNullOrWhiteSpace(input.Name)&&!string.IsNullOrWhiteSpace(input.Hash),"upload_metadata","Numele și amprenta sunt obligatorii.","Name and fingerprint are required.");var name=Path.GetFileName(input.Name);Guard.Require(name.Length is >0 and <=240&&!name.Any(char.IsControl)&&name==input.Name&&!name.Contains('\\')&&Regex.IsMatch(input.Hash,"\\A[0-9a-fA-F]{64}\\z"),"upload_metadata","Numele sau amprenta fișierului nu este validă. Selectează din nou fișierul.","File name or fingerprint is invalid. Select the file again.");
   var mime=Path.GetExtension(name).ToLowerInvariant() switch{".pdf"=>"application/pdf",".png"=>"image/png",".jpg" or ".jpeg"=>"image/jpeg",".heic" or ".heif"=>"image/heic",_=>""};Guard.Require(mime!=""&&mime==input.Mime,"file_type","Selectează un fișier PDF, JPG, PNG sau HEIC.","Select a PDF, JPG, PNG or HEIC file.");
   var grant=new UploadGrant(id,Guid.NewGuid(),Reports.Actor(c.User),input.Version,name,input.Size,mime,input.Hash.ToUpperInvariant(),DateTime.UtcNow.AddMinutes(15));var token=Protector(c).Protect(Serialization.Write(grant));return new{documentId=grant.Document,token,expires=grant.Expires,uploadUrl=$"/reports/{id}/document-bundles/{grant.Document}/content",report.Version};
  })).RequireRateLimiting("document-intake");
  api.MapPost("/reports/{id:guid}/document-bundles/{document:guid}/content",async(Guid id,Guid document,HttpContext c,Db db,Reports svc,IStore store)=>{var grant=Read(c,id,c.Request.Headers["X-Upload-Token"].ToString());Guard.Require(grant.Document==document,"upload_token","Autorizația nu corespunde documentului.","Upload authorisation does not match the document.",403);return await ReceiptFiles.Upload(id,null,c,db,svc,store,grant);}).RequireRateLimiting("document-intake");
  api.MapPost("/reports/{id:guid}/document-bundles/{document:guid}/authorization",async(Guid id,Guid document,VersionRequest input,HttpContext c,Db db,Reports svc)=>await Api.Atomic(db,c,input,async()=>{var report=await svc.Version(id,input.Version,c.User);svc.Edit(report,c.User,input.Reason);var source=report.Attachments.SingleOrDefault(a=>a.Id==document&&!a.Archived);Guard.Require(source!=null&&source.Scan=="AwaitingCompletion","upload_state","Documentul nu așteaptă finalizarea încărcării.","Document is not awaiting upload completion.",409);var grant=new UploadGrant(id,document,Reports.Actor(c.User),report.Version,source!.Name,source.Size,source.Mime,source.Hash,DateTime.UtcNow.AddMinutes(15));return new{token=Protector(c).Protect(Serialization.Write(grant)),report.Version};})).RequireRateLimiting("document-intake");
  api.MapPost("/reports/{id:guid}/document-bundles/{document:guid}/complete",async(Guid id,Guid document,BundleComplete input,HttpContext c,Db db,Reports svc)=>await Api.Atomic(db,c,input,async()=>{
   var grant=Read(c,id,input.Token);Guard.Require(grant.Document==document,"upload_token","Autorizația nu corespunde documentului.","Upload authorisation does not match the document.",403);var report=await svc.Version(id,input.Version,c.User);svc.Edit(report,c.User,input.Reason);var source=report.Attachments.SingleOrDefault(a=>a.Id==document&&!a.Archived);Guard.Require(source!=null&&source.Hash==grant.Hash&&source.Size==grant.Size,"upload_missing","Fișierul nu este încărcat complet. Reîncarcă-l.","File upload is incomplete. Upload it again.",409);if(source!.Scan=="AwaitingCompletion"){source.Scan="Pending";db.Jobs.Add(new(){Kind="ScanReport",Json=source.Id.ToString()});Reports.Touch(report);svc.Log(c.User,id,document.ToString(),"DocumentIntakeCompleted",after:new{source.Hash,source.Size},reason:input.Reason);}return new{e=source,report.Version};
  })).RequireRateLimiting("document-intake");
 }
}

